	/** 
	 * jumpstart the process by instantiating2 Loan
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		loanId = LoanService.getLoanInstance()
		.createLoan( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		LoanService.getLoanInstance()
				.createLoan( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.loanSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Loan : " + successValue.getLoanId());
							  if (successValue.getLoanId().equals(loanId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfLoanList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Loan test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on loan consumed")
					);
			subscriber.loanSubscribe( loanId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Loan : " + successValue.getLoanId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfLoanList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on loan for loanId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Loan. 
	 */
	protected Loan read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Loan" );

		Loan entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Loan with primary key" );
		msg.append( loanId );
		
		LoanFetchOneSummary fetchOneSummary = new LoanFetchOneSummary( loanId );

		try {
			entity = LoanService.getLoanInstance().getLoan( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Loan " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Loan.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Loan." );

		StringBuilder msg = new StringBuilder( "Failed to update a Loan : " );        
		Loan entity = read();
		UpdateLoanCommand command = generateUpdateCommand();
		command.setLoanId(entity.getLoanId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Loan." );

			// for use later on...
			loanId = entity.getLoanId();

			LoanService proxy = LoanService.getLoanInstance();  

			proxy.updateLoan( command ).get();

			LOGGER.info( "-- Successfully saved Loan - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + loanId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Loan.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Loan." );

		Loan entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Loan with id " + loanId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Loan with id " + loanId );

			throw e;
		}

		try{
			LoanService.getLoanInstance().delete( new DeleteLoanCommand( entity.getLoanId() ) ).get();
			LOGGER.info( "-- Successfully deleted Loan with id " + loanId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Loan with id " + loanId );

			throw e;
		}
	}

	/**
	 * get all Loans.
	 */
	protected List<Loan> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Loans:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Loan : " );        
		List<Loan> collection  = new ArrayList<>();

		try {
			// call the static get method on the LoanService
			collection = LoanService.getLoanInstance().getAllLoan();
			assertNotNull( collection, "An Empty collection of Loan was incorrectly returned.");
			
			// Now print out the values
			Loan entity = null;            
			Iterator<Loan> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getLoanId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

